// Pide a Google un token para FCM con la cuenta de servicio (clave en /secrets, fuera de git).
const fs = require('fs');
const crypto = require('crypto');
const sa = JSON.parse(fs.readFileSync($env.FIREBASE_SA_ARCHIVO || '/secrets/firebase-sa.json', 'utf8'));
const entrada = $input.first().json.body || {};
if (!entrada.titulo) throw new Error('Falta el titulo del aviso');
const ahora = Math.floor(Date.now() / 1000);
const b64 = (o) => Buffer.from(JSON.stringify(o)).toString('base64url');
const cabecera = b64({ alg: 'RS256', typ: 'JWT' });
const cuerpo = b64({ iss: sa.client_email, scope: 'https://www.googleapis.com/auth/firebase.messaging', aud: 'https://oauth2.googleapis.com/token', iat: ahora, exp: ahora + 3600 });
const firma = crypto.createSign('RSA-SHA256').update(cabecera + '.' + cuerpo).sign(sa.private_key).toString('base64url');
return [{ json: { assertion: cabecera + '.' + cuerpo + '.' + firma, projectId: sa.project_id, titulo: String(entrada.titulo), cuerpo: String(entrada.cuerpo || ''), tema: String(entrada.tema || 'guardia') } }];
